// src/domain/display/chainPrintName.js
function chainPrintName(chain, town) {
  const own = { label: chain?.label, resource: chain?.resource };
  const route = typeof town === "string" ? town : String(town?.config?.tradeRouteAccess ?? "");
  const row = (
    /** @type {{ requires?: unknown } | undefined} */
    RESOURCE_DATA[
      /** @type {keyof typeof RESOURCE_DATA} */
      String(chain?.resourceKey ?? "")
    ]
  );
  if (!route || !Array.isArray(row?.requires) || row.requires.includes(route)) return own;
  const byAccess = (
    /** @type {Record<string, Record<string, { label: string, resource: string }>>} */
    CHAIN_NAMES_BY_ACCESS[String(chain?.chainId ?? "")]
  );
  const named = byAccess?.[route];
  return named ? { label: named.label, resource: named.resource } : own;
}

