  onset: { base: 0.04, crime: 0.12, security: 0.08, prosperity: 0.06, exposurePenalty: 0.6, min: 5e-3, max: 0.25 },
  // Per-tick organic exposure of a corrupt NPC — the self-cleaning counter-force.
