  exposure: { base: 0.05, security: 0.2, prosperity: 0.12, guild: 0.22, visibility: 0.06, repeatBoost: 0.35, min: 0.01, max: 0.5 },
  // Once a corrupt NPC has eroded to 'notable', each further exposure rolls this
