// src/kernel/slugify.js
function slugify(value, {
  sep = "-",
  max = 0,
  fallback = "",
  empty = "",
  raw = false,
  asciiLower = false
} = {}) {
  const base = raw ? String(value) : String(value || empty);
  const escSep = sep.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const normalizedCase = asciiLower ? base.replace(/[A-Z]/g, (character) => String.fromCharCode(character.charCodeAt(0) + 32)) : base.toLowerCase();
  let out = normalizedCase.replace(/[^a-z0-9]+/g, sep).replace(new RegExp(`^${escSep}+|${escSep}+$`, "g"), "");
  if (max > 0) out = out.slice(0, max);
  return out || fallback;
}

